    features: { eyebrow: 'Fonctionnalités', title: 'Les contrôles essentiels dans un seul flux de travail.', lead: 'Un système de gestion permettant aux petites entreprises d’organiser clients, opérations, stock, achats, finances et documents sans perdre le contexte.', cards: [['Un tableau de bord pour le moment présent', 'Clients, tâches en attente, solde et rythme de l’opération sans parcourir des menus sans fin.'], ['Clients avec contexte', 'Contacts, entreprise, notes, étiquettes, recherche et filtres à proximité de l’historique.'], ['Du devis à l’exécution', 'Devis, approbation, conversion en ordre et suivi sans ressaisie.'], ['Un stock qui guide', 'Entrées, sorties, stock physique, réservations, disponibilité, minimum et réapprovisionnement.'], ['Achats connectés', 'Fournisseurs, commandes, réception, coût moyen et engagement financier dans le même flux.'], ['Finance claire', 'Recettes, dépenses, catégories, périodes, solde, trésorerie, PDF, XLSX et sauvegarde locale.'], ['Les documents deviennent informations', 'Caméra ou import, OCR, texte, fichiers multipages, PDF et partage sur l’appareil.'], ['Assistant Rumman', 'Texte, voix, pièces jointes, historique, favoris, recherche et mémoire à la demande de l’utilisateur.'], ['Protection lors d’un changement d’appareil', 'Lorsque la sauvegarde Android est activée, la base opérationnelle peut être restaurée avec le même compte Google. Android contrôle le processus ; les images et pièces jointes sont exclues.']] },
    how: { eyebrow: 'Fonctionnement', title: 'De l’information dispersée à l’historique qui aide à décider.', lead: 'Le cycle guidé raccourcit le chemin entre comprendre et agir, sans retirer le contrôle à la personne qui travaille.', cycle: [['Capturer', 'Texte, photos, documents et informations opérationnelles entrent dans le flux.'], ['Comprendre', 'Le contenu gagne en structure et en contexte dans l’entreprise.'], ['Confirmer', 'L’utilisateur vérifie et garde la maîtrise des opérations importantes.'], ['Enregistrer', 'L’information devient un historique utile et traçable.'], ['Suivre', 'Rumman fait remonter ce qui demande attention et contexte.']] },
    plans: { eyebrow: 'Forfaits', title: 'Choisissez l’espace dont votre opération a besoin.', lead: 'Des forfaits de lancement pour petites entreprises, avec essai Premium et limites transparentes.', essential: 'Essentiel', pro: 'Pro', team: 'Équipe', monthly: '/mois', annualOne: 'ou R$ 499 par an', annualTwo: 'ou R$ 899 par an', annualThree: 'ou R$ 1 499 par an', featured: 'Plus de capacité', trial: '15 jours d’essai Premium.', trialText: 'L’essai exige l’activation de l’abonnement Google Play. Après la période, le forfait choisi est facturé sauf annulation.', limitText: 'Il n’existe pas de forfait gratuit permanent, d’IA illimitée ni de stockage illimité.' },
    faq: { eyebrow: 'Questions fréquentes', title: 'Ce qu’il faut savoir avant de commencer.', lead: 'Des réponses claires sur le produit, les données, l’intelligence, le stock et la disponibilité.', sideEyebrow: 'Rumman', sideTitle: 'La clarté fait aussi partie du produit.', items: [['Rumman est-il un ERP ?', 'Oui. C’est un ERP guidé pour micro et petites entreprises, réunissant clients, finance, opérations, stock, achats, documents et assistance opérationnelle.'], ['Tout reste-t-il dans le cloud ?', 'Non. Les données détaillées restent principalement sur l’appareil. Les services cloud de Rumman sont limités au compte, à la protection, au résumé, au diagnostic, à l’abonnement et à l’IA demandée. Séparément, lorsque la sauvegarde de l’appareil est activée, Android peut conserver la base opérationnelle dans l’espace privé de sauvegarde du compte Google de l’utilisateur.'], ['Que se passe-t-il si je perds ou remplace mon téléphone ?', 'Lorsque la sauvegarde de l’appareil est activée, Android peut restaurer la base opérationnelle de Rumman avec le même compte Google. Android contrôle cette fonction, limitée à 25 Mo au total par application et exécutée généralement une fois par jour lorsque les conditions système sont réunies. Les identifiants, jetons, caches, images numérisées et pièces jointes sont exclus.'], ['Rumman vend-il mes données ou affiche-t-il des publicités ?', 'Non. Rumman ne vend pas de données et n’affiche pas de publicité.'], ['L’IA prend-elle des décisions financières seule ?', 'Non. Elle est conçue pour guider et organiser. Les opérations importantes restent soumises à la confirmation et au contrôle de l’utilisateur.'], ['Est-il déjà disponible sur Google Play ?', 'Il n’y a pas encore de fiche publique. Le produit est en préparation pour des tests fermés.'], ['Rumman gère-t-il le stock ?', 'Oui. Le flux enregistre les entrées et sorties, sépare stock physique, réservé et disponible, puis guide le réapprovisionnement.']] },
